 function [ dg ] = dgrav2DPrism( den, x0, z0, w, h, xobs, unit )
%     !\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\
% 	! dgrav2DPrism
% 	! Analytical derivative, with respect to prism thickness, of the gravity field
%     ! generated by a 2D vertical prism with constant density contrast.
%     !
%     ! Parameters:
% 	!  den  Input - Density contrast (g/cc)
% 	!  x0   Input - Horizontal centre of the prism
% 	!  z0   Input - Top of the prism
% 	!  w    Input - Prism width
% 	!  h    Input - Prism thickness
% 	!  xobs Input - Observational point where to compute the field
% 	!
% 	! Return:
%     !   Derivative of the field with respect to prism thickness 'h'	
% 	!
% 	! PS. Its assumed z = 0 for observations
% 	!///////////////////////////////////////////////////////////////////////////////
CG = 6.672E-08;
+ w/2.0;
cd = den*1000;
x = xobs - x0; 
p1 = 2*(z0+h)*(1./((z0+h)^2 + x^2) - 1./((z0+h)^2 + (x-w)^2));
p2 = 2*(z0+h)/((z0+h)^2 + (x-w)^2);
p3 = atan((x-w)/(z0+h)) - atan(x/(z0+h)) + x/((z0+h)*(1. + x^2/(z0+h)^2)) - ...
            (x-w)/((z0+h)*(1. + (x-w)^2/(z0+h)^2));
dg = 2*10^5*CG*cd*((x/2)*p1 + (w/2)*p2 - p3);
       
if(unit == 1) 
 dg = dg/1000.0;
end    
end